const ReplyKeyboardMarkupSchema = z
  .object({
    keyboard: z
      .array(z.array(KeyboardButtonSchema))
      .openapi({
        description:
          'Array of button rows, each represented by an Array of [KeyboardButton](https://core.telegram.org/bots/api/#keyboardbutton) objects',
      }),
    one_time_keyboard: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "*Optional*. Requests clients to hide the keyboard as soon as it's been used. The keyboard will still be available, but clients will automatically display the usual letter-keyboard in the chat – the user can press a special button in the input field to see the custom keyboard again. Defaults to *false*.",
      }),
    resize_keyboard: z
      .boolean()
      .default(false)
      .exactOptional()
      .openapi({
        description:
          "*Optional*. Requests clients to resize the keyboard vertically for optimal fit (e.g., make the keyboard smaller if there are just two rows of buttons). Defaults to *false*, in which case the custom keyboard is always of the same height as the app's standard keyboard.",
      }),
    selective: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "*Optional*. Use this parameter if you want to show the keyboard to specific users only. Targets: 1) users that are @mentioned in the *text* of the [Message](https://core.telegram.org/bots/api/#message) object; 2) if the bot's message is a reply (has *reply\\_to\\_message\\_id*), sender of the original message.  \n\n*Example:* A user requests to change the bot's language, bot replies to the request with a keyboard to select the new language. Other users in the group don't see the keyboard.",
      }),
  })
  .openapi({
    description:
      'This object represents a [custom keyboard](https://core.telegram.org/bots#keyboards) with reply options (see [Introduction to bots](https://core.telegram.org/bots#keyboards) for details and examples).',
    externalDocs: { url: 'https://core.telegram.org/bots/api/#replykeyboardmarkup' },
    required: ['keyboard'],
  })
  .openapi('ReplyKeyboardMarkup')

const ReplyKeyboardRemoveSchema = z
  .object({
    remove_keyboard: z
      .boolean()
      .openapi({
        description:
          'Requests clients to remove the custom keyboard (user will not be able to summon this keyboard; if you want to hide the keyboard from sight but keep it accessible, use *one\\_time\\_keyboard* in [ReplyKeyboardMarkup](https://core.telegram.org/bots/api/#replykeyboardmarkup))',
      }),
    selective: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          "*Optional*. Use this parameter if you want to remove the keyboard for specific users only. Targets: 1) users that are @mentioned in the *text* of the [Message](https://core.telegram.org/bots/api/#message) object; 2) if the bot's message is a reply (has *reply\\_to\\_message\\_id*), sender of the original message.  \n\n*Example:* A user votes in a poll, bot returns confirmation message in reply to the vote and removes the keyboard for that user, while still showing the keyboard with poll options to users who haven't voted yet.",
      }),
  })
  .openapi({
    description:
      'Upon receiving a message with this object, Telegram clients will remove the current custom keyboard and display the default letter-keyboard. By default, custom keyboards are displayed until a new keyboard is sent by a bot. An exception is made for one-time keyboards that are hidden immediately after the user presses a button (see [ReplyKeyboardMarkup](https://core.telegram.org/bots/api/#replykeyboardmarkup)).',
    externalDocs: { url: 'https://core.telegram.org/bots/api/#replykeyboardremove' },
    required: ['remove_keyboard'],
  })
  .openapi('ReplyKeyboardRemove')

