export const postSetWebhookRoute = createRoute({
  method: 'post',
  path: '/setWebhook',
  description:
    "Use this method to specify a url and receive incoming updates via an outgoing webhook. Whenever there is an update for the bot, we will send an HTTPS POST request to the specified url, containing a JSON-serialized [Update](https://core.telegram.org/bots/api/#update). In case of an unsuccessful request, we will give up after a reasonable amount of attempts. Returns *True* on success.\n\nIf you'd like to make sure that the Webhook request comes from Telegram, we recommend using a secret path in the URL, e.g. `https://www.example.com/<token>`. Since nobody else knows your bot's token, you can be pretty sure it's us.",
  externalDocs: { url: 'https://core.telegram.org/bots/api/#setwebhook' },
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              allowed_updates: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string()),
                )
                .exactOptional()
                .openapi({
                  description:
                    "A JSON-serialized list of the update types you want your bot to receive. For example, specify [“message”, “edited\\_channel\\_post”, “callback\\_query”] to only receive updates of these types. See [Update](https://core.telegram.org/bots/api/#update) for a complete list of available update types. Specify an empty list to receive all updates regardless of type (default). If not specified, the previous setting will be used.  \nPlease note that this parameter doesn't affect updates created before the call to the setWebhook, so unwanted updates may be received for a short period of time.",
                }),
              certificate: ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                InputFileSchema,
              ).exactOptional(),
              drop_pending_updates: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Pass *True* to drop all pending updates' }),
              ip_address: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The fixed IP address which will be used to send webhook requests instead of the IP address resolved through DNS',
                }),
              max_connections: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .default(40)
                .exactOptional()
                .openapi({
                  description:
                    "Maximum allowed number of simultaneous HTTPS connections to the webhook for update delivery, 1-100. Defaults to *40*. Use lower values to limit the load on your bot's server, and higher values to increase your bot's throughput.",
                }),
              url: z
                .string()
                .openapi({
                  description:
                    'HTTPS url to send updates to. Use an empty string to remove webhook integration',
                }),
            })
            .openapi({ required: ['url'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ ok: z.boolean().default(true), result: z.boolean().default(true) })
            .openapi({ required: ['ok', 'result'] }),
        },
      },
    },
    default: { description: '', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

