export const postUnbanChatMemberRoute = createRoute({
  method: 'post',
  path: '/unbanChatMember',
  description:
    "Use this method to unban a previously kicked user in a supergroup or channel. The user will **not** return to the group or channel automatically, but will be able to join via link, etc. The bot must be an administrator for this to work. By default, this method guarantees that after the call the user is not a member of the chat, but will be able to join it. So if the user is a member of the chat they will also be **removed** from the chat. If you don't want this, use the parameter *only\\_if\\_banned*. Returns *True* on success.",
  externalDocs: { url: 'https://core.telegram.org/bots/api/#unbanchatmember' },
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              chat_id: z
                .union([z.int(), z.string()])
                .openapi({
                  description:
                    'Unique identifier for the target group or username of the target supergroup or channel (in the format `@username`)',
                }),
              only_if_banned: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Do nothing if the user is not banned' }),
              user_id: z.int().openapi({ description: 'Unique identifier of the target user' }),
            })
            .openapi({ required: ['chat_id', 'user_id'] }),
        },
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              chat_id: ((schema) =>
                z.union([
                  z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    schema,
                  ),
                  schema,
                ]))(z.union([z.int(), z.string()])).openapi({
                description:
                  'Unique identifier for the target group or username of the target supergroup or channel (in the format `@username`)',
              }),
              only_if_banned: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Do nothing if the user is not banned' }),
              user_id: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({ description: 'Unique identifier of the target user' }),
            })
            .openapi({ required: ['chat_id', 'user_id'] }),
        },
        'multipart/form-data': {
          schema: z
            .object({
              chat_id: ((schema) =>
                z.union([
                  z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    schema,
                  ),
                  schema,
                ]))(z.union([z.int(), z.string()])).openapi({
                description:
                  'Unique identifier for the target group or username of the target supergroup or channel (in the format `@username`)',
              }),
              only_if_banned: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({ description: 'Do nothing if the user is not banned' }),
              user_id: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({ description: 'Unique identifier of the target user' }),
            })
            .openapi({ required: ['chat_id', 'user_id'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ ok: z.boolean().default(true), result: z.boolean().default(true) })
            .openapi({ required: ['ok', 'result'] }),
        },
      },
    },
    default: { description: '', content: { 'application/json': { schema: ErrorSchema } } },
  },
})

