export const postUploadStickerFileRoute = createRoute({
  method: 'post',
  path: '/uploadStickerFile',
  description:
    'Use this method to upload a .PNG file with a sticker for later use in *createNewStickerSet* and *addStickerToSet* methods (can be used multiple times). Returns the uploaded [File](https://core.telegram.org/bots/api/#file) on success.',
  externalDocs: { url: 'https://core.telegram.org/bots/api/#uploadstickerfile' },
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              png_sticker: ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                InputFileSchema,
              ),
              user_id: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({ description: 'User identifier of sticker file owner' }),
            })
            .openapi({ required: ['user_id', 'png_sticker'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({ ok: z.boolean().default(true), result: FileSchema })
            .openapi({ required: ['ok', 'result'] }),
        },
      },
    },
    default: { description: '', content: { 'application/json': { schema: ErrorSchema } } },
  },
})
